evaluation.contract:
Contract CoCoMEOrderProducts::placeOrder(): Boolean {

            precondition:
          CurrentOrderProduct.oclIsUndefined() = false

            postcondition:
          result = true and CurrentOrderProduct.Status = 'REQUESTED' and if CurrentOrderProduct.OrderEntries->isEmpty() then CurrentOrderProduct.Amount = CurrentOrderProduct.Amount@pre else CurrentOrderProduct.Amount = CurrentOrderProduct.Amount@pre + CurrentOrderProduct.OrderEntries->sumBy(entry : OrderEntry | entry.Subtotal) endif

        }
